const a = $input.item.json;
const data = a.data || a.alert || a;
const out = { agent_id: data.agent?.id || data.agent_id, hashes: [], urls: [], ips: [], command: null, filepath: null };
const hashes = data.syscheck?.hash || data.hash || {};
if (hashes && hashes.sha256) out.hashes.push(hashes.sha256);
if (data.syscheck?.path) out.filepath = data.syscheck.path;
const cmd = data.data?.auditd?.data?.command || data.command || (data.data && data.data.command);
if (cmd) out.command = cmd;
const ip = data.data?.srcip || data.srcip;
if (ip) out.ips.push(ip);
const url = (cmd || '').match(/https?:\/\/[^\s"']+/);
if (url) out.urls.push(url[0]);
return [{ json: { ...out, _raw: a } }];

const iocs = $('Extract IOCs').first().json;
const timeline = $('Get Wazuh Timeline').first().json?.hits?.hits || [];
const vt = $('VirusTotal Lookup').first().json || {};
const vtStats = vt?.data?.attributes?.last_analysis_stats || {};
return [{ json: {
  agent_id: iocs.agent_id,
  hashes: iocs.hashes,
  urls: iocs.urls,
  ips: iocs.ips,
  command: iocs.command,
  filepath: iocs.filepath,
  timeline_count: timeline.length,
  timeline: timeline.map(t => t._source).slice(0,10),
  vt_stats: vtStats
} }];

const ai = $('Tier-3 Analyst Agent').first().json;
let parsed; try { parsed = JSON.parse(ai.choices[0].message.content); } catch(e) { parsed = { verdict: 'Benign', malware_family: null, mitre_techniques: [], behavior_summary: 'AI parse failed', yara_rule: '' }; }
const score = parsed.verdict === 'Malicious' ? 60 : parsed.verdict === 'Suspicious' ? 30 : 0;
return [{ json: {
  timestamp: new Date().toISOString(),
  agent_id: $('Merge Intel').first().json.agent_id,
  tier3_verdict: parsed.verdict,
  malware_family: parsed.malware_family,
  mitre_techniques: parsed.mitre_techniques,
  behavior_summary: parsed.behavior_summary,
  yara_rule: parsed.yara_rule,
  final_score: score,
  case_status: score >= 60 ? 'critical' : score >= 30 ? 'forensic' : 'closed'
} }];
